entries[16040] = { ["name"] = "Arkane Bombe", ["text"] = "Benutzen: Entzieht Zielen im Explosionsradius 381 Mana und fügt ihnen Schaden in Höhe von 50% des abgezogenen Manas zu. Bringt die Ziele im Effektbereich außerdem 5 Sek. lang zum Schweigen.\n\nVersagenschance erhöht, wenn Ihr über Stufe 49 seid. (1 Min Abklingzeit)\nBenötigt Klassische Ingenieurskunst (300)\nVerkaufspreis:" }
entries[16041] = { ["name"] = "Bauplan: Thoriumgranate", ["text"] = "Benutzen: Lehrt Euch die Herstellung einer Thoriumgranate.\nBenötigt Klassische Ingenieurskunst (260)\nVerkaufspreis:\nThoriumgranate\nBenutzen: Fügt Zielen innerhalb von 3 Metern 26 Feuerschaden zu und macht sie 3 Sek. lang handlungsunfähig. Jeglicher Schaden bricht den Effekt ab. Unzuverlässig gegen Ziele über Stufe 49. (1 Min Abklingzeit)\nBenötigt Klassische Ingenieurskunst (260)\nVerkaufspreis:\nBenötigt Thoriumapparat , Thoriumbarren (3), Dichtes Sprengpulver (3), Runenstoff (3)" }
entries[16042] = { ["name"] = "Bauplan: Thoriumapparat", ["text"] = "Benutzen: Lehrt Euch die Herstellung eines Thoriumapparates.\nBenötigt Klassische Ingenieurskunst (260)\nVerkaufspreis:\nThoriumapparat\nHandwerksmaterial\nVerkaufspreis:\nBenötigt Thoriumbarren (3), Runenstoff" }
entries[16043] = { ["name"] = "Bauplan: Thoriumgewehr", ["text"] = "Benutzen: Lehrt Euch die Herstellung eines Thoriumgewehrs.\nBenötigt Klassische Ingenieurskunst (260)\nVerkaufspreis:\nThoriumgewehr\nWird beim Anlegen gebunden\nDistanz Schusswaffe\n5 - 10 Schaden Geschwindigkeit 3.00\n(2.5 Schaden pro Sekunde)\n+3 Beweglichkeit\n+5 Ausdauer\nHaltbarkeit 85 / 85\nVerkaufspreis:\nBenötigt Mithrilrohr (2), Mithrilgehäuse (2), Thoriumapparat (2), Thoriumbarren (4), Tödliches Zielfernrohr\nOptionale Reagenzien: [] (#50)" }
entries[16044] = { ["name"] = "Bauplan: Lebensechte mechanische Kröte", ["text"] = "Benutzen: Lehrt Euch die Herstellung einer lebensechten mechanischen Kröte.\nBenötigt Klassische Ingenieurskunst (265)\nVerkaufspreis:\nLebensechte mechanische Kröte\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick Eure lebensechte mechanische Kröte beschwören oder wieder freigeben.\n80 ( 80)\nVerkaufspreis:\nBenötigt Essenz des Lebens , Thoriumapparat (4), Goldkraftkern , Unverwüstliches Leder" }
entries[16045] = { ["name"] = "Bauplan: Zaubermachtschutzbrille Xtrem-Plus", ["text"] = "Benutzen: Lehrt Euch die Herstellung einer Zaubermachtschutzbrille Xtrem-Plus.\nBenötigt Klassische Ingenieurskunst (270)\nVerkaufspreis:\nZaubermachtschutzbrille Xtrem-Plus\nWird beim Anlegen gebunden\nKopf Stoff\n3 Rüstung\n+6 Intelligenz\nHaltbarkeit 70 / 70\nBenötigt Klassische Ingenieurskunst (1)\nVerkaufspreis:\nBenötigt Zaubermachtschutzbrille Xtrem , Sternrubin (4), Verzaubertes Leder (2), Runenstoff (8)" }
entries[16046] = { ["name"] = "Bauplan: Meisterliche Zielattrappe", ["text"] = "Benutzen: Lehrt Euch die Herstellung einer meisterlichen Zielattrappe.\nBenötigt Klassische Ingenieurskunst (275)\nVerkaufspreis:\nMeisterliche Zielattrappe\nBenutzen: Lässt eine Zielattrappe auf den Boden fallen, die in der Nähe befindliche Monster dazu bringt, sie anzugreifen. Die Attrappe bleibt bis zu ihrer Zerstörung aktiv, maximal jedoch für 15 Sekunden. (2 Min Abklingzeit)\nBenötigt Klassische Ingenieurskunst (275)\nVerkaufspreis:\nBenötigt Mithrilgehäuse , Thoriumröhre , Thoriumapparat (2), Echtsilberbarren , Unverwüstliches Leder (2), Runenstoff (4)" }
