entries[16052] = { ["name"] = "Bauplan: Modularer Stimmenverstärker", ["text"] = "Benutzen: Lehrt Euch die Herstellung eines modularen Stimmenverstärkers.\nBenötigt Klassische Ingenieurskunst (290)\nVerkaufspreis:\nModularer Stimmenverstärker\nWird beim Anlegen gebunden\nHals\nAnlegen: Verringert die Wirkungsdauer jeglicher Stille- und Unterbrechungseffekte gegen den Träger um 10%. Dieser Effekt ist nicht mit anderen Effekten dieser Art stapelbar.\nVerkaufspreis:\nBenötigt Empfindlicher Arkanitwandler (2), Goldkraftkern , Thoriumapparat , Großer Opal" }
entries[16053] = { ["name"] = "Bauplan: Schutzbrille des Meisteringenieurs", ["text"] = "Benutzen: Lehrt Euch die Herstellung einer Schutzbrille des Meisteringenieurs.\nBenötigt Klassische Ingenieurskunst (290)\nVerkaufspreis:\nSchutzbrille des Meisteringenieurs\nWird beim Anlegen gebunden\nKopf Stoff\n3 Rüstung\n+5 Ausdauer\n+ 7 Vielseitigkeit\nHaltbarkeit 70 / 70\nBenötigt Klassische Ingenieurskunst (1)\nVerkaufspreis:\nBenötigt Feuerschutzbrille , Gewaltiger Smaragd (2), Verzaubertes Leder (4)" }
entries[16054] = { ["name"] = "Bauplan: Arkanitdrachling", ["text"] = "Benutzen: Lehrt Euch die Herstellung eines Arkanitdrachlings.\nBenötigt Klassische Ingenieurskunst (300)\nVerkaufspreis:\nArkanitdrachling\nWird beim Anlegen gebunden\nEinzigartig anlegbar\nSchmuck\nBenutzen: Aktiviert Euren Arkanitdrachling, damit er 1 Min. lang für Euch kämpft. (5 Min Abklingzeit)\nBenötigt Klassische Ingenieurskunst (300)\nVerkaufspreis:\nBenötigt Mechanischer Mithrildrachling , Empfindlicher Arkanitwandler (4)" }
entries[16055] = { ["name"] = "Bauplan: Arkane Bombe", ["text"] = "Benutzen: Lehrt Euch die Herstellung einer arkanen Bombe.\nBenötigt Klassische Ingenieurskunst (300)\nVerkaufspreis:\nArkane Bombe\nBenutzen: Entzieht Zielen im Explosionsradius 381 Mana und fügt ihnen Schaden in Höhe von 50% des abgezogenen Manas zu. Bringt die Ziele im Effektbereich außerdem 5 Sek. lang zum Schweigen.\n\nVersagenschance erhöht, wenn Ihr über Stufe 49 seid. (1 Min Abklingzeit)\nBenötigt Klassische Ingenieurskunst (300)\nVerkaufspreis:\nBenötigt Empfindlicher Arkanitwandler , Thoriumbarren (3), Runenstoff" }
entries[16056] = { ["name"] = "Bauplan: Fehlerloses Arkanitgewehr", ["text"] = "Benutzen: Lehrt Euch die Herstellung eines fehlerlosen Arkanitgewehrs.\nBenötigt Klassische Ingenieurskunst (300)\nVerkaufspreis:\nFehlerloses Arkanitgewehr\nWird beim Anlegen gebunden\nDistanz Schusswaffe\n5 - 10 Schaden Geschwindigkeit 3.00\n(2.5 Schaden pro Sekunde)\n+4 Beweglichkeit\n+5 Ausdauer\nErhöht Eure kritische Trefferwertung um + 8.\nHaltbarkeit 100 / 100\nVerkaufspreis:\nBenötigt Arkanitbarren (10), Thoriumröhre (2), Essenz des Feuers (2), Essenz der Erde (2), Azerothischer Diamant (2), Verzaubertes Leder (2)\nOptionale Reagenzien: [] (#50)" }
