entries[16110] = { ["name"] = "Rezept: Monsteromelett", ["text"] = "Benutzen: Lehrt Euch, wie man ein Monsteromelett zubereitet.\nBenötigt Klassische Kochkunst (225)\nVerkaufspreis:\nMonsteromelett\nBenutzen: Stellt im Verlauf von 30 Sek. ( 175 * 30 / 5) Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet 15 Min. lang 2 Ausdauer und Vielseitigkeit.\nVerkaufspreis:\nBenötigt Riesenei" }
entries[16111] = { ["name"] = "Rezept: Gewürzter Chilikrebs", ["text"] = "Benutzen: Lehrt Euch, wie man gewürzten Chilikrebs zubereitet.\nBenötigt Klassische Kochkunst (225)\nVerkaufspreis:\nGewürzter Chilikrebs\nBenutzen: Stellt im Verlauf von 30 Sek. ( 175 * 30 / 5) Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet 15 Min. lang 2 Ausdauer und Vielseitigkeit.\nVerkaufspreis:\nBenötigt Zartes Krebsfleisch" }
